			ld (de), a
			or a
			jr z, p_cybsys_putmsg_si0_e
			inc hl
			inc de
			djnz p_cybsys_putmsg_si0
			xor a
			ld (de), a
p_cybsys_putmsg_si0_e:
			ld hl, 0
			ld (var_cybsys_putmsg_k), hl
			ld (p_cybsys_putmsg_rs), sp
			ld sp, p_cybsys_putmsg
			jp ntc_xn
p_cybsys_putmsg_r:		; end of putmsg
			ld sp, (p_cybsys_putmsg_rs)
			jp ntc_xn
p_cybsys_getmsg_c:		; call getmsg (normal)
			xor a
			ld (var_cybsys_getmsg_getmsg), a
			ld hl, 0
			ld (var_cybsys_getmsg_k), hl
			ld (p_cybsys_getmsg_rs), sp
			ld sp, p_cybsys_getmsg
			jp ntc_xn
